## 自定义过滤器

**操作过滤器示例**：
```csharp
public class LogActionFilter : IAsyncActionFilter
{
    private readonly ILogger<LogActionFilter> _logger;

    public LogActionFilter(ILogger<LogActionFilter> logger)
    {
        _logger = logger;
    }

    public async Task OnActionExecutionAsync(
        ActionExecutingContext context,
        ActionExecutionDelegate next)
    {
        var stopwatch = Stopwatch.StartNew();

        _logger.LogInformation($"操作 {context.ActionDescriptor.DisplayName} 开始执行");

        var resultContext = await next();

        stopwatch.Stop();

        if (resultContext.Exception != null)
        {
            _logger.LogError(resultContext.Exception, "操作执行失败");
        }
        else
        {
            _logger.LogInformation($"操作执行完成，耗时 {stopwatch.ElapsedMilliseconds}ms");
        }
    }
}
```

**异常过滤器示例**：
```csharp
public class GlobalExceptionFilter : IAsyncExceptionFilter
{
    private readonly ILogger<GlobalExceptionFilter> _logger;

    public GlobalExceptionFilter(ILogger<GlobalExceptionFilter> logger)
    {
        _logger = logger;
    }

    public async Task OnExceptionAsync(ExceptionContext context)
    {
        _logger.LogError(context.Exception, "未处理的异常");

        context.Result = new ObjectResult(new
        {
            Code = 500,
            Message = "服务器内部错误"
        })
        {
            StatusCode = 500
        };

        context.ExceptionHandled = true;
    }
}
```

**资源过滤器示例（缓存）**：
```csharp
public class CacheResourceFilter : IAsyncResourceFilter
{
    private static readonly Dictionary<string, (object Result, DateTime Expiry)> Cache = new();
    private readonly int _durationSeconds;

    public CacheResourceFilter(int durationSeconds)
    {
        _durationSeconds = durationSeconds;
    }

    public async Task OnResourceExecutionAsync(
        ResourceExecutingContext context,
        ResourceExecutionDelegate next)
    {
        var cacheKey = context.HttpContext.Request.Path.ToString();

        if (Cache.TryGetValue(cacheKey, out var cached) && cached.Expiry > DateTime.UtcNow)
        {
            context.Result = cached.Result as IActionResult;
            return; // 短路管道
        }

        var resultContext = await next();

        if (resultContext.Result is ObjectResult objectResult)
        {
            Cache[cacheKey] = (objectResult, DateTime.UtcNow.AddSeconds(_durationSeconds));
        }
    }
}
```


## 过滤器与中间件的区别

**中间件**：
- 在请求管道早期执行
- 全局处理所有请求
- 不了解 MVC 上下文

**过滤器**：
- 在 MVC 管道内执行
- 可以针对特定控制器/操作
- 可以访问 MVC 上下文（ActionContext）

using System;
using System.Diagnostics;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace FiltersPipelineDemo
{
    // 授权过滤器
    public class CustomAuthorizeFilter : IAsyncAuthorizationFilter
    {
        private readonly string _requiredRole;

        public CustomAuthorizeFilter(string requiredRole)
        {
            _requiredRole = requiredRole;
        }

        public Task OnAuthorizationAsync(AuthorizationFilterContext context)
        {
            var user = context.HttpContext.User;
            if (!user.Identity.IsAuthenticated)
            {
                context.Result = new UnauthorizedResult();
                return Task.CompletedTask;
            }

            if (!user.IsInRole(_requiredRole))
            {
                context.Result = new ForbidResult();
                return Task.CompletedTask;
            }

            return Task.CompletedTask;
        }
    }

    // 资源过滤器 - 请求限流
    public class RateLimitResourceFilter : IAsyncResourceFilter
    {
        private static readonly Dictionary<string, DateTime> LastRequestTime = new();
        private readonly int _requestsPerMinute;

        public RateLimitResourceFilter(int requestsPerMinute)
        {
            _requestsPerMinute = requestsPerMinute;
        }

        public async Task OnResourceExecutionAsync(
            ResourceExecutingContext context,
            ResourceExecutionDelegate next)
        {
            var clientIp = context.HttpContext.Connection.RemoteIpAddress?.ToString();
            var key = $"{clientIp}:{context.HttpContext.Request.Path}";

            if (LastRequestTime.TryGetValue(key, out var lastTime))
            {
                var elapsed = DateTime.UtcNow - lastTime;
                if (elapsed.TotalSeconds < 60.0 / _requestsPerMinute)
                {
                    context.Result = new ObjectResult(new { Message = "请求过于频繁" })
                    {
                        StatusCode = 429
                    };
                    return;
                }
            }

            LastRequestTime[key] = DateTime.UtcNow;
            await next();
        }
    }

    // 操作过滤器 - 日志记录
    public class LogActionFilter : IAsyncActionFilter
    {
        private readonly ILogger<LogActionFilter> _logger;

        public LogActionFilter(ILogger<LogActionFilter> logger)
        {
            _logger = logger;
        }

        public async Task OnActionExecutionAsync(
            ActionExecutingContext context,
            ActionExecutionDelegate next)
        {
            var actionName = context.ActionDescriptor.DisplayName;
            var parameters = context.ActionArguments;

            _logger.LogInformation($"开始执行操作: {actionName}");
            _logger.LogInformation($"参数: {System.Text.Json.JsonSerializer.Serialize(parameters)}");

            var stopwatch = Stopwatch.StartNew();
            var resultContext = await next();
            stopwatch.Stop();

            if (resultContext.Exception != null)
            {
                _logger.LogError(resultContext.Exception,
                    $"操作 {actionName} 执行失败，耗时 {stopwatch.ElapsedMilliseconds}ms");
            }
            else
            {
                _logger.LogInformation(
                    $"操作 {actionName} 执行完成，耗时 {stopwatch.ElapsedMilliseconds}ms，" +
                    $"结果类型: {resultContext.Result?.GetType().Name}");
            }
        }
    }

    // 异常过滤器 - 全局异常处理
    public class GlobalExceptionFilter : IAsyncExceptionFilter
    {
        private readonly ILogger<GlobalExceptionFilter> _logger;

        public GlobalExceptionFilter(ILogger<GlobalExceptionFilter> logger)
        {
            _logger = logger;
        }

        public async Task OnExceptionAsync(ExceptionContext context)
        {
            _logger.LogError(context.Exception, "发生未处理的异常");

            var statusCode = context.Exception switch
            {
                ArgumentException => 400,
                UnauthorizedAccessException => 401,
                KeyNotFoundException => 404,
                _ => 500
            };

            context.Result = new ObjectResult(new
            {
                Code = statusCode,
                Message = context.Exception.Message,
                TraceId = Activity.Current?.Id ?? context.HttpContext.TraceIdentifier
            })
            {
                StatusCode = statusCode
            };

            context.ExceptionHandled = true;
        }
    }

    // 结果过滤器 - 响应包装
    public class ApiResponseResultFilter : IAsyncResultFilter
    {
        public async Task OnResultExecutionAsync(
            ResultExecutingContext context,
            ResultExecutionDelegate next)
        {
            if (context.Result is ObjectResult objectResult)
            {
                var wrappedResult = new
                {
                    Code = objectResult.StatusCode ?? 200,
                    Message = "成功",
                    Data = objectResult.Value,
                    Timestamp = DateTime.UtcNow
                };

                objectResult.Value = wrappedResult;
            }

            await next();
        }
    }

    // 过滤器特性
    public class TimingAttribute : ActionFilterAttribute
    {
        private Stopwatch _stopwatch;

        public override void OnActionExecuting(ActionExecutingContext context)
        {
            _stopwatch = Stopwatch.StartNew();
        }

        public override void OnActionExecuted(ActionExecutedContext context)
        {
            _stopwatch.Stop();
            context.HttpContext.Response.Headers.Add("X-Execution-Time",
                $"{_stopwatch.ElapsedMilliseconds}ms");
        }
    }

    // 使用过滤器的控制器
    [ApiController]
    [Route("api/[controller]")]
    public class ProductsController : ControllerBase
    {
        [HttpGet]
        [Timing]
        [ServiceFilter(typeof(LogActionFilter))]
        public IActionResult GetAll()
        {
            return Ok(new[] { "Product1", "Product2" });
        }

        [HttpGet("{id}")]
        [Timing]
        public IActionResult GetById(int id)
        {
            if (id <= 0)
                throw new ArgumentException("ID 必须大于 0");

            if (id > 100)
                throw new KeyNotFoundException("产品不存在");

            return Ok($"Product {id}");
        }
    }

    // 注册过滤器
    public static class ServiceCollectionExtensions
    {
        public static IServiceCollection AddCustomFilters(this IServiceCollection services)
        {
            services.AddScoped<LogActionFilter>();
            services.AddScoped<GlobalExceptionFilter>();
            services.AddScoped<ApiResponseResultFilter>();

            services.AddControllers(options =>
            {
                // 全局过滤器
                options.Filters.AddService<GlobalExceptionFilter>();
                options.Filters.AddService<ApiResponseResultFilter>();
                options.Filters.Add(new RateLimitResourceFilter(100));
            });

            return services;
        }
    }
}
